 pg.locator('#open-space').click();pg.locator('#space-question').fill('GSE42568');pg.locator('#space-search').click();expect(pg.locator('.candidate')).to_have_count(1,timeout=40000);pg.locator('[data-shortlist]').click();expect(pg.locator('#space-shortlist')).to_contain_text('1/2');pg.locator('[data-files]').click();expect(pg.locator('.public-file')).to_have_count(1,timeout=40000);pg.screenshot(path=str(O/'space_live.png'));check('live_search_shortlist_and_file_verification');pg.locator('#close-space').click();pg.locator('#wordmark [data-view="study"]').click();pg.locator('#new-data').click();pg.locator('[data-start-task="evaluate_predictions"]').click();check('prediction_setup_has_three_stages',pg.locator('[data-setup-step]').count()==3)
 (O/'receipt.json').write_text(json.dumps({'status':'PASS','checks':checks,'errors':errors},indent=2));assert not errors;b.close()
